// -- Space location (Runtime-scoped) -----------------------------------------
//
// The runtime emits `space.opened` when it opens a directory path as a space
// and `space.seen` on each re-open. Both fold into the `spaces` Runtime-
// scoped projection (see `ship-space::spaces_projection`). Identity is owned
// by the space — the `space_id` (entity_id of the envelope) is a mint-once
// nanoid generated by `ship-space::identity::ensure_identity_for`; the `path`
// field is the location, never an identity.
//
// `Activate` and its `project.switched` event are gone (operator 2026-07-09:
// multi-window kills the open-one-at-a-time world).

use serde::{Deserialize, Serialize};

#[derive(Debug, Serialize, Deserialize)]
pub struct SpaceOpened {
    /// Location on this device — where the space currently lives. Not an
    /// identity; the canonical home of identity is `spaces.space_id`.
    pub path: String,
    /// Human label (final-path segment at mint; the runtime may rename later
    /// through the projection).
    pub name: String,
    /// RFC3339 timestamp the space was first opened on this device.
    pub opened_at: String,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct SpaceSeen {
    /// RFC3339 timestamp of the re-open.
    pub seen_at: String,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct StackRegistered {
    /// Absolute stack root on this device — the directory whose
    /// `stack.config.ts` marks it. A location, not an identity.
    pub root_path: String,
    /// RFC3339 timestamp of registration.
    pub registered_at: String,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct StackInstalled {
    /// Registry-issued package path (the install identity).
    pub path: String,
    /// Resolved version (the registry-stated exact version).
    pub version: String,
    /// Absolute stack root on this device — the unpacked library row.
    pub root_path: String,
    /// Canonical content hash — matches the registry attestation AND the
    /// cache key. The single hash that flows registry ↔ attestation ↔ disk.
    pub content_hash: String,
    /// RFC3339 timestamp of installation.
    pub installed_at: String,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct StackUnregistered {
    /// Registry-issued package path (the install identity).
    pub path: String,
    /// Resolved version (the registry-stated exact version).
    pub version: String,
    /// Absolute stack root the library row materialised at.
    pub root_path: String,
    /// RFC3339 timestamp of unregistration.
    pub unregistered_at: String,
}
